#!/usr/bin/env bash
# Write royal-road/deploy/lightspeed/41-ols-shim-configmap.yaml from
# rr_ols_shim.py. Run after editing the shim; CI fails if the two differ.
#
#   royal-road/plugins/lightspeed-service/render-configmap.sh [--check]
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
out=$here/../../deploy/lightspeed/41-ols-shim-configmap.yaml

render() {
  cat <<'HEADER'
# Generated by royal-road/plugins/lightspeed-service/render-configmap.sh from
# rr_ols_shim.py. Do not edit; edit the .py file and re-run the script.
apiVersion: v1
kind: ConfigMap
metadata:
  name: rr-ols-shim
  namespace: openshift-lightspeed
data:
  rr_ols_shim.py: |
HEADER
  sed -e 's/^\(.\)/    \1/' "$here/rr_ols_shim.py"
}

if [[ ${1:-} == --check ]]; then
  if ! diff -u "$out" <(render); then
    echo "41-ols-shim-configmap.yaml is out of date; run $0" >&2
    exit 1
  fi
  echo "41-ols-shim-configmap.yaml is up to date"
else
  render >"$out"
fi
